    out = []
    n = 0
    for i, line in enumerate(lines):
        out.append(line)
        m = re.match(r'^(\s*(?:///\s?)?)(\s*)node_kind(?::[^,]*)?,$', line)
        if not m:
            continue
        back = lines[max(0, i - 8):i]
        if not any(re.search(r'CodeBlock \{\s*$', b) for b in back):
            continue
        if any('..' in b and 'CodeBlock' in b for b in back):
            continue
        code = None
        for j in range(i + 1, i + 8):
            mm = re.match(r'^\s*(?:///\s?)?\s*code(?::\s*(.*?))?,\s*$', lines[j])
            if mm:
                code = mm.group(1) or 'code'
                break
        if code is None:
            sys.exit(f"{f}:{i} no code")
        if code == 'String::new()':
            span = '0..0'
        elif code in ('code.to_owned()', 'code.to_string()', 'code'):
            span = '0..code.len()'
        else:
            lm = re.fullmatch(r'("(?:[^"\\]|\\.)*")\.to_string\(\)', code)
            if lm:
                span = f'0..{len(ast.literal_eval(lm.group(1)))}'
            else:
                span = '?? ' + code
        pre = m.group(1) + m.group(2)
        out.append(f'{pre}span: {span},')
        out.append(f'{pre}parent_index: None,')
        n += 1
    open(f, 'w').write('\n'.join(out))
    print(f, n)

